# AvxVnni prefers VEX; AVX512v3 supplies the same operations with EVEX.
MultiplyWideningAndAdd(v{W}i32,v{W}u8,v{W}i8) @storage = DN2CPP_ISA_VNNI({mm}_dpbusd, $0, $1, $2) for W in 128,256
MultiplyWideningAndAdd(v{W}i32,v{W}i16,v{W}i16) @storage = DN2CPP_ISA_VNNI({mm}_dpwssd, $0, $1, $2) for W in 128,256
MultiplyWideningAndAddSaturate(v{W}i32,v{W}u8,v{W}i8) @storage = DN2CPP_ISA_VNNI({mm}_dpbusds, $0, $1, $2) for W in 128,256
MultiplyWideningAndAddSaturate(v{W}i32,v{W}i16,v{W}i16) @storage = DN2CPP_ISA_VNNI({mm}_dpwssds, $0, $1, $2) for W in 128,256
